INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('free-trial-001', 'free-trial', 'free-trial-01', 'Good morning. How are you?', 'सुप्रभात। आप कैसे हैं?', 1, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('free-trial-002', 'free-trial', 'free-trial-01', 'My name is Priya. What is your name?', 'मेरा नाम प्रिया है। आपका नाम क्या है?', 2, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('free-trial-003', 'free-trial', 'free-trial-01', 'I am from India. Where are you from?', 'मैं भारत से हूँ। आप कहाँ से हैं?', 3, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('free-trial-004', 'free-trial', 'free-trial-01', 'I wake up at 6 o''clock every day.', 'मैं हर दिन 6 बजे उठता हूँ।', 4, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('free-trial-005', 'free-trial', 'free-trial-01', 'Can you please call me later?', 'क्या आप मुझे बाद में कॉल कर सकते हैं?', 5, 1);
