INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-713', 'beginner', 'beginner-29', 'Let us celebrate this moment together.', 'चलो इस पल को साथ मिलकर मनाते हैं।', 713, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-714', 'beginner', 'beginner-29', 'Congratulations on your success!', 'आपकी सफलता पर बधाई!', 714, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-715', 'beginner', 'beginner-29', 'We light candles on Diwali night.', 'हम दिवाली की रात दीये जलाते हैं।', 715, 1);
