INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-717', 'beginner', 'beginner-29', 'I received many good wishes today.', 'मुझे आज बहुत सारी शुभकामनाएँ मिलीं।', 717, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-718', 'beginner', 'beginner-29', 'We sing and dance during celebrations.', 'हम उत्सव के दौरान गाते और नाचते हैं।', 718, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-719', 'beginner', 'beginner-29', 'Please come and join the celebration.', 'कृपया उत्सव में शामिल होइए।', 719, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-720', 'beginner', 'beginner-29', 'May your dreams come true!', 'आपके सपने पूरे हों!', 720, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-721', 'beginner', 'beginner-29', 'The festival brings happiness to everyone.', 'त्योहार सभी के लिए खुशी लाता है।', 721, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-722', 'beginner', 'beginner-29', 'We exchange sweets with neighbours.', 'हम पड़ोसियों के साथ मिठाइयाँ बाँटते हैं।', 722, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-723', 'beginner', 'beginner-29', 'I am looking forward to the celebration.', 'मैं उत्सव का इंतज़ार कर रहा हूँ।', 723, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-724', 'beginner', 'beginner-29', 'Best wishes for the new beginning!', 'नई शुरुआत के लिए शुभकामनाएँ!', 724, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('beginner-725', 'beginner', 'beginner-29', 'Festivals bring families closer.', 'त्योहार परिवारों को करीब लाते हैं।', 725, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-001', 'intermediate', 'intermediate-01', 'Let me explain the situation to you.', 'मुझे आपको स्थिति समझाने दें।', 1, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-002', 'intermediate', 'intermediate-01', 'This is what happened yesterday.', 'कल ऐसा हुआ था।', 2, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-003', 'intermediate', 'intermediate-01', 'I was waiting for the bus when I saw him.', 'मैं बस का इंतज़ार कर रहा था तभी मैंने उसे देखा।', 3, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-004', 'intermediate', 'intermediate-01', 'The problem started around 3 PM.', 'समस्या लगभग 3 बजे शुरू हुई।', 4, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-005', 'intermediate', 'intermediate-01', 'I have been facing this issue for a week.', 'मैं एक हफ्ते से इस समस्या का सामना कर रहा हूँ।', 5, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-006', 'intermediate', 'intermediate-01', 'The main issue is the delay in delivery.', 'मुख्य समस्या डिलीवरी में देरी है।', 6, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-007', 'intermediate', 'intermediate-01', 'Let me show you what I mean.', 'आइए मैं आपको दिखाता हूँ कि मेरा क्या मतलब है।', 7, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-008', 'intermediate', 'intermediate-01', 'It happened just like this.', 'बिल्कुल ऐसे ही हुआ।', 8, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-009', 'intermediate', 'intermediate-01', 'I was about to leave when the phone rang.', 'मैं जाने ही वाला था कि फोन बजा।', 9, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-010', 'intermediate', 'intermediate-01', 'This is not what I expected.', 'मुझे ऐसी उम्मीद नहीं थी।', 10, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-011', 'intermediate', 'intermediate-01', 'The situation is more complicated than it seems.', 'स्थिति जितनी लगती है उससे कहीं अधिक जटिल है।', 11, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-012', 'intermediate', 'intermediate-01', 'Let me explain what happened step by step.', 'मुझे कदम दर कदम समझाने दें कि क्या हुआ।', 12, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-013', 'intermediate', 'intermediate-01', 'The first thing that went wrong was the payment.', 'सबसे पहले भुगतान में गड़बड़ हुई।', 13, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-014', 'intermediate', 'intermediate-01', 'In other words, we need to start again.', 'दूसरे शब्दों में, हमें फिर से शुरू करना होगा।', 14, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-015', 'intermediate', 'intermediate-01', 'This is a common problem in our area.', 'हमारे क्षेत्र में यह एक आम समस्या है।', 15, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-016', 'intermediate', 'intermediate-01', 'Have you faced this situation before?', 'क्या आपने पहले इस स्थिति का सामना किया है?', 16, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-017', 'intermediate', 'intermediate-01', 'I can describe the scene in detail.', 'मैं दृश्य का विस्तार से वर्णन कर सकता हूँ।', 17, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-018', 'intermediate', 'intermediate-01', 'It was a very unusual experience.', 'यह एक बहुत ही असामान्य अनुभव था।', 18, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-019', 'intermediate', 'intermediate-01', 'The reason for the problem is quite simple.', 'समस्या का कारण काफी सरल है।', 19, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-020', 'intermediate', 'intermediate-01', 'We need to find a solution quickly.', 'हमें जल्दी से एक समाधान खोजना होगा।', 20, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-021', 'intermediate', 'intermediate-01', 'Let me break it down for you.', 'मैं आपके लिए इसे सरल करता हूँ।', 21, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-022', 'intermediate', 'intermediate-01', 'I will explain everything in detail.', 'मैं सब कुछ विस्तार से समझाऊँगा।', 22, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-023', 'intermediate', 'intermediate-01', 'That clears up a lot of confusion.', 'इससे बहुत सारा भ्रम दूर हो गया।', 23, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-024', 'intermediate', 'intermediate-01', 'I appreciate you explaining it clearly.', 'मैं सराहना करता हूँ कि आपने स्पष्ट रूप से समझाया।', 24, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-025', 'intermediate', 'intermediate-01', 'Now I understand the full picture.', 'अब मुझे पूरी तस्वीर समझ आ गई।', 25, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-026', 'intermediate', 'intermediate-02', 'In my opinion, this is the best option.', 'मेरी राय में, यह सबसे अच्छा विकल्प है।', 26, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-027', 'intermediate', 'intermediate-02', 'I personally believe we should wait.', 'मैं व्यक्तिगत रूप से मानता हूँ कि हमें इंतज़ार करना चाहिए।', 27, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-028', 'intermediate', 'intermediate-02', 'From my point of view, it is a good idea.', 'मेरे दृष्टिकोण से, यह एक अच्छा विचार है।', 28, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-029', 'intermediate', 'intermediate-02', 'I completely agree with your suggestion.', 'मैं आपके सुझाव से पूरी तरह सहमत हूँ।', 29, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-030', 'intermediate', 'intermediate-02', 'That makes sense. I think you are right.', 'यह समझ में आता है। मुझे लगता है आप सही हैं।', 30, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-031', 'intermediate', 'intermediate-02', 'I see your point, but I have a different view.', 'मैं आपकी बात समझता हूँ, लेकिन मेरा एक अलग दृष्टिकोण है।', 31, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-032', 'intermediate', 'intermediate-02', 'I am not sure I agree with that.', 'मुझे यकीन नहीं है कि मैं इससे सहमत हूँ।', 32, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-033', 'intermediate', 'intermediate-02', 'You have a valid point there.', 'आपकी बात वाजिब है।', 33, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-034', 'intermediate', 'intermediate-02', 'I could not agree more.', 'मैं इससे अधिक सहमत नहीं हो सकता।', 34, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-035', 'intermediate', 'intermediate-02', 'That is exactly what I was thinking.', 'यह बिल्कुल वही है जो मैं सोच रहा था।', 35, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-036', 'intermediate', 'intermediate-02', 'I respectfully disagree with you.', 'मैं विनम्रतापूर्वक आपसे असहमत हूँ।', 36, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-037', 'intermediate', 'intermediate-02', 'Let us agree to disagree.', 'चलो असहमत होने पर सहमत होते हैं।', 37, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-038', 'intermediate', 'intermediate-02', 'I respect your opinion even though I disagree.', 'भले ही मैं असहमत हूँ, मैं आपकी राय का सम्मान करता हूँ।', 38, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-039', 'intermediate', 'intermediate-02', 'Can I share my thoughts on this?', 'क्या मैं इस पर अपने विचार साझा कर सकता हूँ?', 39, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-040', 'intermediate', 'intermediate-02', 'I think we should go ahead with the plan.', 'मुझे लगता है हमें योजना के साथ आगे बढ़ना चाहिए।', 40, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-041', 'intermediate', 'intermediate-02', 'That sounds like a practical solution.', 'यह एक व्यावहारिक समाधान लगता है।', 41, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-042', 'intermediate', 'intermediate-02', 'Let me think about it and get back to you.', 'मुझे इसके बारे में सोचने दें और फिर बताऊँ।', 42, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-043', 'intermediate', 'intermediate-02', 'I appreciate your honest opinion.', 'मैं आपकी ईमानदार राय की सराहना करता हूँ।', 43, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-044', 'intermediate', 'intermediate-02', 'Everyone is entitled to their opinion.', 'हर किसी को अपनी राय रखने का अधिकार है।', 44, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-045', 'intermediate', 'intermediate-02', 'We considered all the views.', 'हमने सभी विचारों पर विचार किया।', 45, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-046', 'intermediate', 'intermediate-02', 'The majority agrees with the proposal.', 'बहुमत प्रस्ताव से सहमत है।', 46, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-047', 'intermediate', 'intermediate-02', 'Opinions make conversations interesting.', 'राय बातचीत को दिलचस्प बनाती हैं।', 47, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-048', 'intermediate', 'intermediate-02', 'I value different perspectives.', 'मैं अलग-अलग दृष्टिकोणों को महत्व देता हूँ।', 48, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-049', 'intermediate', 'intermediate-02', 'We reached a common understanding.', 'हम एक सामान्य समझ पर पहुँचे।', 49, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-050', 'intermediate', 'intermediate-02', 'Respectful disagreement is healthy.', 'सम्मानजनक असहमति स्वस्थ है।', 50, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-051', 'intermediate', 'intermediate-03', 'Have you considered another approach?', 'क्या आपने कोई और तरीका सोचा है?', 51, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-052', 'intermediate', 'intermediate-03', 'I would suggest trying a different method.', 'मैं एक अलग तरीका आज़माने का सुझाव दूँगा।', 52, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-053', 'intermediate', 'intermediate-03', 'Why do we not discuss this further?', 'क्यों न हम इस पर और चर्चा करें?', 53, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-054', 'intermediate', 'intermediate-03', 'Let me offer a different perspective.', 'मुझे एक अलग दृष्टिकोण देने दें।', 54, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-055', 'intermediate', 'intermediate-03', 'I strongly recommend taking this course.', 'मैं जोरदार सिफारिश करता हूँ कि यह कोर्स करें।', 55, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-056', 'intermediate', 'intermediate-03', 'My advice would be to practice every day.', 'मेरी सलाह होगी कि रोज़ अभ्यास करें।', 56, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-057', 'intermediate', 'intermediate-03', 'If I were you, I would start early.', 'अगर मैं आपकी जगह होता, तो जल्दी शुरू करता।', 57, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-058', 'intermediate', 'intermediate-03', 'You should consider all the options.', 'आपको सभी विकल्पों पर विचार करना चाहिए।', 58, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-059', 'intermediate', 'intermediate-03', 'Let us look at the pros and cons first.', 'चलो पहले फायदे और नुकसान देखते हैं।', 59, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-060', 'intermediate', 'intermediate-03', 'I would recommend speaking with an expert.', 'मैं एक विशेषज्ञ से बात करने की सिफारिश करूँगा।', 60, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-061', 'intermediate', 'intermediate-03', 'That is a valid point, but have you thought about the cost?', 'यह एक उचित बात है, लेकिन क्या आपने लागत के बारे में सोचा है?', 61, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-062', 'intermediate', 'intermediate-03', 'You might want to check the details again.', 'आप शायद विवरण फिर से जाँचना चाहें।', 62, 1);
