INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-220', 'intermediate', 'intermediate-09', 'We arranged everything perfectly.', 'हमने सब कुछ बिल्कुल सही व्यवस्थित किया।', 220, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-221', 'intermediate', 'intermediate-09', 'Planning ahead makes arrangements easy.', 'पहले से योजना बनाने से व्यवस्थाएँ आसान होती हैं।', 221, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-222', 'intermediate', 'intermediate-09', 'I will send you the invitation details.', 'मैं आपको आमंत्रण का विवरण भेज दूँगा।', 222, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-223', 'intermediate', 'intermediate-09', 'Let us coordinate the logistics.', 'चलो रसद का समन्वय करते हैं।', 223, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-224', 'intermediate', 'intermediate-09', 'Everything went according to plan.', 'सब कुछ योजना के अनुसार हुआ।', 224, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-225', 'intermediate', 'intermediate-09', 'Good planning leads to smooth events.', 'अच्छी योजना सुचारू आयोजन की ओर ले जाती है।', 225, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-226', 'intermediate', 'intermediate-10', 'The reason I am saying this is because of safety.', 'मैं ऐसा इसलिए कह रहा हूँ क्योंकि सुरक्षा महत्वपूर्ण है।', 226, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-227', 'intermediate', 'intermediate-10', 'Let me give you an example to illustrate.', 'मुझे आपको एक उदाहरण देकर समझाने दें।', 227, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-228', 'intermediate', 'intermediate-10', 'What I mean is that we need more time.', 'मेरा मतलब यह है कि हमें और समय चाहिए।', 228, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-229', 'intermediate', 'intermediate-10', 'The main reason for this decision is cost.', 'इस निर्णय का मुख्य कारण लागत है।', 229, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-230', 'intermediate', 'intermediate-10', 'I chose this option because it is more efficient.', 'मैंने यह विकल्प चुना क्योंकि यह अधिक कुशल है।', 230, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-231', 'intermediate', 'intermediate-10', 'There are three reasons for this.', 'इसके तीन कारण हैं।', 231, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-232', 'intermediate', 'intermediate-10', 'First of all, it saves time.', 'सबसे पहले, यह समय बचाता है।', 232, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-233', 'intermediate', 'intermediate-10', 'Secondly, it is more affordable.', 'दूसरा, यह अधिक किफायती है।', 233, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-234', 'intermediate', 'intermediate-10', 'Finally, it is better for the environment.', 'अंत में, यह पर्यावरण के लिए बेहतर है।', 234, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-235', 'intermediate', 'intermediate-10', 'In simple terms, the system is not working.', 'सीधे शब्दों में, सिस्टम काम नहीं कर रहा है।', 235, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-236', 'intermediate', 'intermediate-10', 'Let me put it this way.', 'मुझे इसे इस तरह से समझाने दें।', 236, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-237', 'intermediate', 'intermediate-10', 'The basic idea is very simple.', 'मूल विचार बहुत सरल है।', 237, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-238', 'intermediate', 'intermediate-10', 'I would like to add something to that point.', 'मैं उस बिंदु पर कुछ जोड़ना चाहूँगा।', 238, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-239', 'intermediate', 'intermediate-10', 'Let me expand on what I said earlier.', 'मुझे अपनी पिछली बात का विस्तार करने दें।', 239, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-240', 'intermediate', 'intermediate-10', 'The reason we failed is lack of planning.', 'हमारी असफलता का कारण योजना की कमी है।', 240, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-241', 'intermediate', 'intermediate-10', 'That explains why the project got delayed.', 'इससे पता चलता है कि परियोजना क्यों विलंबित हुई।', 241, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-242', 'intermediate', 'intermediate-10', 'I think I have made my point clear.', 'मुझे लगता है मैंने अपनी बात स्पष्ट कर दी है।', 242, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-243', 'intermediate', 'intermediate-10', 'Does that make sense to you?', 'क्या यह आपको समझ में आया?', 243, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-244', 'intermediate', 'intermediate-10', 'I am glad you asked that question.', 'मुझे खुशी है कि आपने यह सवाल पूछा।', 244, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-245', 'intermediate', 'intermediate-10', 'The reason behind this change is customer feedback.', 'इस बदलाव के पीछे का कारण ग्राहक प्रतिक्रिया है।', 245, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-246', 'intermediate', 'intermediate-10', 'Let me show you how this works.', 'मुझे आपको दिखाने दें कि यह कैसे काम करता है।', 246, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-247', 'intermediate', 'intermediate-10', 'This is a classic example of good teamwork.', 'यह अच्छी टीमवर्क का एक उत्कृष्ट उदाहरण है।', 247, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-248', 'intermediate', 'intermediate-10', 'Giving clear reasons builds understanding.', 'स्पष्ट कारण बताने से समझ बनती है।', 248, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-249', 'intermediate', 'intermediate-10', 'Logic supports every good decision.', 'तर्क हर अच्छे निर्णय का समर्थन करता है।', 249, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-250', 'intermediate', 'intermediate-10', 'Explaining well is a valuable skill.', 'अच्छी तरह समझाना एक मूल्यवान कौशल है।', 250, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-251', 'intermediate', 'intermediate-11', 'This restaurant is better than the one we went to last time.', 'यह रेस्तराँ पिछली बार वाले से बेहतर है।', 251, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-252', 'intermediate', 'intermediate-11', 'I prefer tea over coffee in the morning.', 'मैं सुबह कॉफी की तुलना में चाय पसंद करता हूँ।', 252, 1);
