INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-255', 'intermediate', 'intermediate-11', 'The quality is much better than I expected.', 'गुणवत्ता मेरी उम्मीद से कहीं बेहतर है।', 255, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-256', 'intermediate', 'intermediate-11', 'I like this one because it is more practical.', 'मुझे यह पसंद है क्योंकि यह अधिक व्यावहारिक है।', 256, 1);
