INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-258', 'intermediate', 'intermediate-11', 'Compared to last year, sales have increased.', 'पिछले साल की तुलना में, बिक्री में वृद्धि हुई है।', 258, 1);
