INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-262', 'intermediate', 'intermediate-11', 'The difference between these two is significant.', 'इन दोनों के बीच अंतर महत्वपूर्ण है।', 262, 1);
