INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-264', 'intermediate', 'intermediate-11', 'Which one do you think is better?', 'आपको कौन सा बेहतर लगता है?', 264, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-265', 'intermediate', 'intermediate-11', 'This is similar to what we discussed earlier.', 'यह वैसा ही है जैसा हमने पहले चर्चा की थी।', 265, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-266', 'intermediate', 'intermediate-11', 'Both are good, but my favourite is the red one.', 'दोनों अच्छे हैं, लेकिन मेरा पसंदीदा लाल वाला है।', 266, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-267', 'intermediate', 'intermediate-11', 'I would not recommend that option.', 'मैं उस विकल्प की सिफारिश नहीं करूँगा।', 267, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-268', 'intermediate', 'intermediate-11', 'The new version is far more user-friendly.', 'नया वर्शन कहीं अधिक उपयोगकर्ता-अनुकूल है।', 268, 1);
