INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-270', 'intermediate', 'intermediate-11', 'The only difference is the colour.', 'एकमात्र अंतर रंग का है।', 270, 1);
