INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-275', 'intermediate', 'intermediate-11', 'Choose what suits you best.', 'वह चुनिए जो आपके लिए सबसे उपयुक्त हो।', 275, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-276', 'intermediate', 'intermediate-12', 'This is not an easy situation to handle.', 'यह संभालना आसान स्थिति नहीं है।', 276, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-277', 'intermediate', 'intermediate-12', 'I am trying to stay calm under pressure.', 'मैं दबाव में शांत रहने की कोशिश कर रहा हूँ।', 277, 1);
