INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-284', 'intermediate', 'intermediate-12', 'I have considered all the alternatives.', 'मैंने सभी विकल्पों पर विचार कर लिया है।', 284, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-285', 'intermediate', 'intermediate-12', 'The best course of action is to wait.', 'सबसे अच्छा कदम इंतज़ार करना है।', 285, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-286', 'intermediate', 'intermediate-12', 'I never back down from a challenge.', 'मैं कभी चुनौती से पीछे नहीं हटता।', 286, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-287', 'intermediate', 'intermediate-12', 'This is a test of our patience.', 'यह हमारे धैर्य की परीक्षा है।', 287, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-288', 'intermediate', 'intermediate-12', 'I believe we can turn this around.', 'मुझे विश्वास है हम इसे बदल सकते हैं।', 288, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-289', 'intermediate', 'intermediate-12', 'Sometimes you have to take a leap of faith.', 'कभी-कभी आपको विश्वास की छलांग लगानी पड़ती है।', 289, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-290', 'intermediate', 'intermediate-12', 'I will support whatever you decide.', 'जो भी आप तय करेंगे, मैं उसका समर्थन करूँगा।', 290, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-291', 'intermediate', 'intermediate-12', 'We can get through this together.', 'हम एक साथ इससे उबर सकते हैं।', 291, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-292', 'intermediate', 'intermediate-12', 'Every problem has a solution.', 'हर समस्या का एक समाधान है।', 292, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-293', 'intermediate', 'intermediate-12', 'I am proud of how we handled this.', 'मुझे गर्व है कि हमने इसे कैसे संभाला।', 293, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-294', 'intermediate', 'intermediate-12', 'Stay positive even in tough times.', 'कठिन समय में भी सकारात्मक रहिए।', 294, 1);
