INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-296', 'intermediate', 'intermediate-12', 'We faced the situation bravely.', 'हमने स्थिति का साहस से सामना किया।', 296, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-297', 'intermediate', 'intermediate-12', 'There is always a way forward.', 'आगे बढ़ने का रास्ता हमेशा होता है।', 297, 1);
