INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-300', 'intermediate', 'intermediate-12', 'We came out stronger from this situation.', 'हम इस स्थिति से और मजबूत होकर निकले।', 300, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-301', 'intermediate', 'intermediate-13', 'So, what have you been up to lately?', 'तो, आप इन दिनों क्या कर रहे हैं?', 301, 1);
