INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-307', 'intermediate', 'intermediate-13', 'No way! Congratulations!', 'नहीं! बधाई हो!', 307, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-308', 'intermediate', 'intermediate-13', 'To be honest, I was not expecting that.', 'सच कहूँ तो, मुझे ऐसी उम्मीद नहीं थी।', 308, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-309', 'intermediate', 'intermediate-13', 'It was a pleasant surprise.', 'यह एक सुखद आश्चर्य था।', 309, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-310', 'intermediate', 'intermediate-13', 'I am really happy for you.', 'मैं आपके लिए वाकई खुश हूँ।', 310, 1);
