INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-315', 'intermediate', 'intermediate-13', 'That is a smart move.', 'यह एक समझदारी भरा कदम है।', 315, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-316', 'intermediate', 'intermediate-13', 'I will keep you updated.', 'मैं आपको अपडेट करता रहूँगा।', 316, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-317', 'intermediate', 'intermediate-13', 'Sounds good to me.', 'मुझे ठीक लगता है।', 317, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-318', 'intermediate', 'intermediate-13', 'Let me think about it first.', 'मुझे पहले इसके बारे में सोचने दें।', 318, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-319', 'intermediate', 'intermediate-13', 'I am in! Let us do it.', 'मैं तैयार हूँ! चलो करते हैं।', 319, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-320', 'intermediate', 'intermediate-13', 'That is the best news today!', 'यह आज की सबसे अच्छी खबर है!', 320, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-321', 'intermediate', 'intermediate-13', 'We should do this more often.', 'हमें ऐसा और अक्सर करना चाहिए।', 321, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-322', 'intermediate', 'intermediate-13', 'It was great talking to you.', 'आपसे बात करके बहुत अच्छा लगा।', 322, 1);
