INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-324', 'intermediate', 'intermediate-13', 'Stay in touch, okay?', 'संपर्क में रहिए, ठीक है?', 324, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-325', 'intermediate', 'intermediate-13', 'Natural English comes with practice.', 'प्राकृतिक अंग्रेज़ी अभ्यास से आती है।', 325, 1);
