INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-329', 'intermediate', 'intermediate-14', 'Speaking fluently takes time and effort.', 'धाराप्रवाह रूप से बोलने में समय और प्रयास लगता है।', 329, 1);
