INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-332', 'intermediate', 'intermediate-14', 'The more you speak, the more confident you become.', 'जितना अधिक आप बोलते हैं, उतने ही आत्मविश्वासी बनते हैं।', 332, 1);
