INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-336', 'intermediate', 'intermediate-14', 'My friends notice my improvement.', 'मेरे दोस्तों ने मेरा सुधार देखा है।', 336, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-337', 'intermediate', 'intermediate-14', 'Fluency means speaking smoothly.', 'धाराप्रवाहता का मतलब है सहज रूप से बोलना।', 337, 1);
