INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-342', 'intermediate', 'intermediate-14', 'I think in English sometimes.', 'मैं कभी-कभी अंग्रेज़ी में सोचता हूँ।', 342, 1);
