INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-346', 'intermediate', 'intermediate-14', 'I am becoming a fluent speaker.', 'मैं एक धाराप्रवाह वक्ता बन रहा हूँ।', 346, 1);
