INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('intermediate-349', 'intermediate', 'intermediate-14', 'Fluency opens many doors in life.', 'धाराप्रवाहता जीवन में कई दरवाज़े खोलती है।', 349, 1);
