INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-001', 'advanced', 'advanced-01', 'I would like to schedule a meeting to discuss the quarterly results.', 'मैं त्रैमासिक परिणामों पर चर्चा के लिए मीटिंग शेड्यूल करना चाहूँगा।', 1, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-002', 'advanced', 'advanced-01', 'Could we arrange a conference call with the stakeholders?', 'क्या हम हितधारकों के साथ कॉन्फ्रेंस कॉल कर सकते हैं?', 2, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-003', 'advanced', 'advanced-01', 'Please find the attached report for your reference.', 'कृपया आपके संदर्भ के लिए संलग्न रिपोर्ट देखें।', 3, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-004', 'advanced', 'advanced-01', 'I look forward to your feedback on the proposal.', 'मैं प्रस्ताव पर आपकी प्रतिक्रिया की प्रतीक्षा कर रहा हूँ।', 4, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-005', 'advanced', 'advanced-01', 'I am writing to express my interest in this opportunity.', 'मैं इस अवसर में अपनी रुचि दर्शाने के लिए लिख रहा हूँ।', 5, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-006', 'advanced', 'advanced-01', 'It has been a pleasure collaborating with your team.', 'आपकी टीम के साथ सहयोग करके खुशी हुई।', 6, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-007', 'advanced', 'advanced-01', 'I would like to bring an important matter to your attention.', 'मैं आपका ध्यान एक महत्वपूर्ण मामले की ओर दिलाना चाहूँगा।', 7, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-008', 'advanced', 'advanced-01', 'Could you provide an update on the project status?', 'क्या आप परियोजना की स्थिति पर अपडेट दे सकते हैं?', 8, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-009', 'advanced', 'advanced-01', 'I appreciate your prompt response to my query.', 'मेरे प्रश्न पर आपकी त्वरित प्रतिक्रिया की सराहना करता हूँ।', 9, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-010', 'advanced', 'advanced-01', 'Let us align our goals to ensure mutual success.', 'आइए आपसी सफलता के लिए अपने लक्ष्यों को संरेखित करें।', 10, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-011', 'advanced', 'advanced-01', 'The deliverables are on track for the deadline.', 'समय सीमा के लिए डिलिवरेबल सही रास्ते पर हैं।', 11, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-012', 'advanced', 'advanced-01', 'I need your input to finalize the strategy.', 'रणनीति को अंतिम रूप देने के लिए मुझे आपके इनपुट की ज़रूरत है।', 12, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-013', 'advanced', 'advanced-01', 'Let us establish clear expectations from the outset.', 'शुरू से ही स्पष्ट अपेक्षाएँ स्थापित करें।', 13, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-014', 'advanced', 'advanced-01', 'I will ensure the deliverables meet the required standards.', 'मैं सुनिश्चित करूँगा कि डिलिवरेबल आवश्यक मानकों को पूरा करें।', 14, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-015', 'advanced', 'advanced-01', 'Please acknowledge receipt of this message.', 'कृपया इस संदेश की प्राप्ति की पुष्टि करें।', 15, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-016', 'advanced', 'advanced-01', 'I propose that we revisit our timeline.', 'मैं प्रस्ताव करता हूँ कि हम अपनी समय-सीमा पर पुनर्विचार करें।', 16, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-017', 'advanced', 'advanced-01', 'We need to prioritize our tasks based on urgency.', 'हमें तात्कालिकता के आधार पर अपने कार्यों को प्राथमिकता देनी है।', 17, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-018', 'advanced', 'advanced-01', 'I would be happy to assist you with this matter.', 'मुझे इस मामले में आपकी सहायता करने में खुशी होगी।', 18, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('advanced-019', 'advanced', 'advanced-01', 'Please do not hesitate to reach out if you have concerns.', 'यदि आपको कोई चिंता हो तो कृपया संपर्क करने में संकोच न करें।', 19, 1);
