INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-333', 'interview', 'interview-13', 'Pause and think before answering.', 'उत्तर देने से पहले रुककर सोचिए।', 333, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-334', 'interview', 'interview-13', 'Listen carefully to the question.', 'प्रश्न को ध्यान से सुनिए।', 334, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-335', 'interview', 'interview-13', 'Ask for clarification if needed.', 'ज़रूरत हो तो स्पष्टीकरण माँगिए।', 335, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-336', 'interview', 'interview-13', 'Your confidence shows in your voice.', 'आपका आत्मविश्वास आपकी आवाज़ में दिखता है।', 336, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-337', 'interview', 'interview-13', 'Practice speaking in front of a mirror.', 'आईने के सामने बोलने का अभ्यास कीजिए।', 337, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-338', 'interview', 'interview-13', 'Take a moment to collect your thoughts.', 'अपने विचारों को एकत्र करने के लिए एक पल लीजिए।', 338, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-339', 'interview', 'interview-13', 'Avoid using filler words like umm.', 'उम्म जैसे शब्दों का उपयोग न करें।', 339, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-340', 'interview', 'interview-13', 'Be enthusiastic about the role.', 'भूमिका के प्रति उत्साहित रहिए।', 340, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-341', 'interview', 'interview-13', 'Dress smartly for confidence.', 'आत्मविश्वास के लिए स्मार्ट कपड़े पहनिए।', 341, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-342', 'interview', 'interview-13', 'A firm handshake shows confidence.', 'मजबूत हाथ मिलाना आत्मविश्वास दर्शाता है।', 342, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-343', 'interview', 'interview-13', 'Do not fidget during the interview.', 'साक्षात्कार के दौरान इधर-उधर न हिलें।', 343, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-344', 'interview', 'interview-13', 'Keep your answers concise.', 'अपने उत्तर संक्षिप्त रखिए।', 344, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-345', 'interview', 'interview-13', 'Show passion in your tone.', 'अपने स्वर में जुनून दिखाइए।', 345, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-346', 'interview', 'interview-13', 'Be yourself and be honest.', 'स्वयं बनिए और ईमानदार रहिए।', 346, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-347', 'interview', 'interview-13', 'Confidence comes from preparation.', 'आत्मविश्वास तैयारी से आता है।', 347, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-348', 'interview', 'interview-13', 'Positive energy impresses interviewers.', 'सकारात्मक ऊर्जा साक्षात्कारकर्ताओं को प्रभावित करती है।', 348, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-349', 'interview', 'interview-13', 'I believe in myself.', 'मुझे खुद पर विश्वास है।', 349, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-350', 'interview', 'interview-13', 'Every interview makes me stronger.', 'हर साक्षात्कार मुझे मजबूत बनाता है।', 350, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-351', 'interview', 'interview-14', 'I sent a thank you email after the interview.', 'साक्षात्कार के बाद मैंने धन्यवाद ईमेल भेजा।', 351, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-352', 'interview', 'interview-14', 'Thank you for giving me your time today.', 'आज मुझे अपना समय देने के लिए धन्यवाद।', 352, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-353', 'interview', 'interview-14', 'I appreciate the opportunity to interview.', 'साक्षात्कार का अवसर देने के लिए मैं आभारी हूँ।', 353, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-354', 'interview', 'interview-14', 'I enjoyed meeting the team.', 'मुझे टीम से मिलकर अच्छा लगा।', 354, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-355', 'interview', 'interview-14', 'I am very interested in this position.', 'मुझे इस पद में बहुत रुचि है।', 355, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-356', 'interview', 'interview-14', 'I am following up on my application.', 'मैं अपने आवेदन के संबंध में अनुवर्ती कर रहा हूँ।', 356, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-357', 'interview', 'interview-14', 'Have you made a decision about the role?', 'क्या आपने भूमिका के बारे में निर्णय लिया है?', 357, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-358', 'interview', 'interview-14', 'I would like to know the status of my application.', 'मैं अपने आवेदन की स्थिति जानना चाहूँगा।', 358, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-359', 'interview', 'interview-14', 'I am available for another round of discussion.', 'मैं चर्चा के एक और दौर के लिए उपलब्ध हूँ।', 359, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-360', 'interview', 'interview-14', 'Please let me know if you need more information.', 'अगर आपको और जानकारी चाहिए तो कृपया बताइए।', 360, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-361', 'interview', 'interview-14', 'I am excited about the possibility of joining.', 'मैं जुड़ने की संभावना को लेकर उत्साहित हूँ।', 361, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-362', 'interview', 'interview-14', 'I will wait for your response.', 'मैं आपके उत्तर का इंतज़ार करूँगा।', 362, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-363', 'interview', 'interview-14', 'Following up shows your interest.', 'अनुवर्ती करना आपकी रुचि दर्शाता है।', 363, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-364', 'interview', 'interview-14', 'A polite follow-up is appreciated.', 'विनम्र अनुवर्ती की सराहना की जाती है।', 364, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-365', 'interview', 'interview-14', 'I thanked the panel for their time.', 'मैंने पैनल को उनके समय के लिए धन्यवाद दिया।', 365, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-366', 'interview', 'interview-14', 'I shared my portfolio with them.', 'मैंने उनके साथ अपना पोर्टफोलियो साझा किया।', 366, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-367', 'interview', 'interview-14', 'I asked about the next steps.', 'मैंने अगले चरणों के बारे में पूछा।', 367, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-368', 'interview', 'interview-14', 'I stayed positive while waiting.', 'इंतज़ार करते हुए मैं सकारात्मक रहा।', 368, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-369', 'interview', 'interview-14', 'The recruiter said they will revert soon.', 'भर्तीकर्ता ने कहा वे जल्द बताएँगे।', 369, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-370', 'interview', 'interview-14', 'I prepared for the next round.', 'मैंने अगले दौर की तैयारी की।', 370, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-371', 'interview', 'interview-14', 'I kept my documents ready.', 'मैंने अपने दस्तावेज़ तैयार रखे।', 371, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-372', 'interview', 'interview-14', 'Patience is important after an interview.', 'साक्षात्कार के बाद धैर्य महत्वपूर्ण है।', 372, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-373', 'interview', 'interview-14', 'I learned from this experience.', 'मैंने इस अनुभव से सीखा।', 373, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-374', 'interview', 'interview-14', 'Good things come to those who wait.', 'इंतज़ार करने वालों को अच्छी चीज़ें मिलती हैं।', 374, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-375', 'interview', 'interview-14', 'I am ready for new opportunities.', 'मैं नए अवसरों के लिए तैयार हूँ।', 375, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-376', 'interview', 'interview-15', 'Good morning. Please have a seat.', 'सुप्रभात। कृपया बैठिए।', 376, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-377', 'interview', 'interview-15', 'Thank you. Good morning to you too.', 'धन्यवाद। आपको भी सुप्रभात।', 377, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-378', 'interview', 'interview-15', 'So, tell me about yourself.', 'तो, अपने बारे में बताइए।', 378, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-379', 'interview', 'interview-15', 'I am a graduate with three years of experience.', 'मैं तीन साल के अनुभव वाला स्नातक हूँ।', 379, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-380', 'interview', 'interview-15', 'Why are you interested in this role?', 'आप इस भूमिका में रुचि क्यों रखते हैं?', 380, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-381', 'interview', 'interview-15', 'I am passionate about this field of work.', 'मैं काम के इस क्षेत्र के प्रति भावुक हूँ।', 381, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-382', 'interview', 'interview-15', 'What are your strengths?', 'आपकी ताकतें क्या हैं?', 382, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-383', 'interview', 'interview-15', 'My strengths are dedication and learning ability.', 'मेरी ताकतें समर्पण और सीखने की क्षमता हैं।', 383, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-384', 'interview', 'interview-15', 'Where do you see yourself in five years?', 'आप खुद को पाँच साल में कहाँ देखते हैं?', 384, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-385', 'interview', 'interview-15', 'I see myself growing with this company.', 'मैं खुद को इस कंपनी के साथ बढ़ता हुआ देखता हूँ।', 385, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-386', 'interview', 'interview-15', 'Do you have any questions for us?', 'क्या आपके पास हमारे लिए कोई प्रश्न हैं?', 386, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-387', 'interview', 'interview-15', 'Yes, I would like to know about the team.', 'हाँ, मैं टीम के बारे में जानना चाहूँगा।', 387, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-388', 'interview', 'interview-15', 'When can you join us?', 'आप हमसे कब जुड़ सकते हैं?', 388, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-389', 'interview', 'interview-15', 'I can join within fifteen days.', 'मैं पंद्रह दिनों के भीतर जुड़ सकता हूँ।', 389, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-390', 'interview', 'interview-15', 'We will inform you about the result.', 'हम आपको परिणाम के बारे में सूचित करेंगे।', 390, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-391', 'interview', 'interview-15', 'Thank you for the interview.', 'साक्षात्कार के लिए धन्यवाद।', 391, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-392', 'interview', 'interview-15', 'It was nice talking to you.', 'आपसे बात करके अच्छा लगा।', 392, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-393', 'interview', 'interview-15', 'We will be in touch with you.', 'हम आपसे संपर्क में रहेंगे।', 393, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-394', 'interview', 'interview-15', 'I look forward to hearing from you.', 'मैं आपसे सुनने की उम्मीद करता हूँ।', 394, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-395', 'interview', 'interview-15', 'Have a great day, sir.', 'आपका दिन शुभ हो, महोदय।', 395, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-396', 'interview', 'interview-15', 'The conversation went very well.', 'बातचीत बहुत अच्छी रही।', 396, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-397', 'interview', 'interview-15', 'I answered every question confidently.', 'मैंने हर प्रश्न का उत्तर आत्मविश्वास से दिया।', 397, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-398', 'interview', 'interview-15', 'I practiced this conversation many times.', 'मैंने इस बातचीत का कई बार अभ्यास किया।', 398, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-399', 'interview', 'interview-15', 'Practice makes interviews easier.', 'अभ्यास साक्षात्कार को आसान बनाता है।', 399, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('interview-400', 'interview', 'interview-15', 'I am one step closer to my dream job.', 'मैं अपने सपनों की नौकरी के एक कदम और करीब हूँ।', 400, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('corporate-001', 'corporate', 'corporate-01', 'Good morning, everyone. How is everyone today?', 'सुप्रभात, सभी को। आज सब कैसे हैं?', 1, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('corporate-002', 'corporate', 'corporate-01', 'Good morning, sir. It is nice to see you.', 'सुप्रभात, महोदय। आपको देखकर अच्छा लगा।', 2, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('corporate-003', 'corporate', 'corporate-01', 'Welcome to the office!', 'ऑफिस में आपका स्वागत है!', 3, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('corporate-004', 'corporate', 'corporate-01', 'I hope you had a good weekend.', 'मुझे उम्मीद है आपका वीकेंड अच्छा रहा।', 4, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('corporate-005', 'corporate', 'corporate-01', 'Nice to see you all at the meeting.', 'मीटिंग में आप सभी को देखकर अच्छा लगा।', 5, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('corporate-006', 'corporate', 'corporate-01', 'Let us start the day with a quick update.', 'चलो दिन की शुरुआत एक त्वरित अपडेट से करते हैं।', 6, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('corporate-007', 'corporate', 'corporate-01', 'How are things going with your project?', 'आपकी परियोजना के साथ चीज़ें कैसी चल रही हैं?', 7, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('corporate-008', 'corporate', 'corporate-01', 'Everything is on track, thank you.', 'सब कुछ सही रास्ते पर है, धन्यवाद।', 8, 1);
