INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('business-116', 'business', 'business-05', 'Let us put the agreement in writing.', 'चलो समझौते को लिखित रूप में रखते हैं।', 116, 1);
