INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('business-118', 'business', 'business-05', 'We agreed on the terms finally.', 'हम अंततः शर्तों पर सहमत हुए।', 118, 1);
