INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('business-124', 'business', 'business-05', 'We closed the deal successfully.', 'हमने सौदा सफलतापूर्वक पूरा किया।', 124, 1);
INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('business-125', 'business', 'business-05', 'Business is about building relationships.', 'व्यवसाय संबंध बनाने के बारे में है।', 125, 1);
