INSERT OR REPLACE INTO sentences (id, course_id, lesson_id, english, hindi, sort_order, is_free) VALUES ('business-146', 'business', 'business-06', 'The supplier quality is consistent.', 'आपूर्तिकर्ता की गुणवत्ता सुसंगत है।', 146, 1);
